// Booking rules 1-5 (content type, size, JSON object, room, title), rule order and id handling.
import { describe, it, before, after } from 'node:test';
import assert from 'node:assert/strict';
import {
  startServer, request, postBooking, validBooking, JSON_TYPE, makeTempDir, removeDir,
} from './helpers/server-harness.mjs';

const SIX_KEYS = ['date', 'end', 'id', 'room', 'start', 'title'];
const MSG = {
  type: 'content type must be application/json',
  size: 'body too large',
  object: 'body must be a JSON object',
  room: 'room must be one of Aurora, Borealis, Cosmos',
  title: 'title must be 1 to 80 characters',
  date: 'date must be a valid YYYY-MM-DD date',
  start: 'start must be HH:MM',
  end: 'end must be HH:MM',
  order: 'end must be after start',
};

let dayCounter = 0;
function freshDate() {
  dayCounter += 1;
  return new Date(Date.UTC(2030, 0, 1 + dayCounter)).toISOString().slice(0, 10);
}

/** A valid booking on a date no other test uses; `undefined` overrides drop the key. */
function booking(overrides = {}) {
  return validBooking({ date: freshDate(), ...overrides });
}

function label(value) {
  return value === undefined ? '<missing>' : JSON.stringify(value);
}

function useServer() {
  const ctx = {};
  before(async () => {
    ctx.dir = await makeTempDir();
    ctx.server = await startServer({ cwd: ctx.dir, env: { DATA_FILE: 'data.json' } });
    ctx.port = ctx.server.port;
  });
  after(async () => {
    if (ctx.server) await ctx.server.stop();
    if (ctx.dir) await removeDir(ctx.dir);
  });
  return ctx;
}

function assertJsonError(res, status, message) {
  assert.equal(res.status, status);
  assert.equal(res.headers['content-type'], JSON_TYPE);
  assert.deepEqual(res.json(), { error: message });
}

function assertCreated(res, expected) {
  assert.equal(res.status, 201);
  assert.equal(res.headers['content-type'], JSON_TYPE);
  const body = res.json();
  assert.deepEqual(Object.keys(body).sort(), SIX_KEYS);
  assert.equal(typeof body.id, 'number');
  assert.deepEqual(body, { id: body.id, ...expected });
  return body;
}

/** Bytes of `obj` as JSON padded with spaces inside the object to exactly `size` bytes. */
function paddedBody(obj, size) {
  const json = JSON.stringify(obj);
  const pad = size - Buffer.byteLength(json);
  assert.ok(pad >= 0);
  const text = '{' + ' '.repeat(pad) + json.slice(1);
  assert.equal(Buffer.byteLength(text), size);
  return Buffer.from(text);
}

/** Body with an ignored "pad" key of 'é' (2 bytes each) plus spaces, exactly `size` bytes. */
function accentBody(obj, size) {
  const base = Buffer.byteLength(JSON.stringify({ ...obj, pad: '' }));
  const count = Math.floor((size - base) / 2);
  const text = JSON.stringify({ ...obj, pad: 'é'.repeat(count) });
  const spaces = ' '.repeat(size - Buffer.byteLength(text));
  const full = spaces + text;
  assert.equal(Buffer.byteLength(full), size);
  return { buffer: Buffer.from(full), text: full };
}

function chunked(buffer, chunkSize = 1000) {
  const chunks = [];
  for (let i = 0; i < buffer.length; i += chunkSize) chunks.push(buffer.subarray(i, i + chunkSize));
  return chunks;
}

describe('rule order ladder', () => {
  const ctx = useServer();
  const ok = { room: 'Aurora', title: 'ok', date: '2030-12-01', start: '09:00', end: '10:00' };
  const bad = 'x';
  const rawCases = [
    ['no content type, 20000 bytes', undefined, Buffer.alloc(20000, 'x'), 415, MSG.type],
    ['text/plain, 20000 bytes', 'text/plain', Buffer.alloc(20000, 'x'), 415, MSG.type],
    ['json, 10001 bytes invalid', 'application/json', Buffer.alloc(10001, 'x'), 413, MSG.size],
    ['json, "[1"', 'application/json', '[1', 400, MSG.object],
  ];
  for (const [name, contentType, body, status, message] of rawCases) {
    it(name, async () => {
      assert.ok(Buffer.byteLength(body) >= 2);
      assertJsonError(await postBooking(ctx.port, body, { contentType, raw: true }), status, message);
    });
  }

  const fieldCases = [
    ['room first', { room: bad, title: '', date: bad, start: bad, end: bad }, MSG.room],
    ['title next', { ...ok, title: '', date: bad, start: bad, end: bad }, MSG.title],
    ['date next', { ...ok, date: bad, start: bad, end: bad }, MSG.date],
    ['start next', { ...ok, start: bad, end: bad }, MSG.start],
    ['end next', { ...ok, end: bad }, MSG.end],
  ];
  for (const [name, body, message] of fieldCases) {
    it(name, async () => assertJsonError(await postBooking(ctx.port, body), 400, message));
  }

  it('end before start beats an overlap (400, not 409)', async () => {
    assertCreated(await postBooking(ctx.port, ok), ok);
    const res = await postBooking(ctx.port, { ...ok, start: '10:00', end: '09:00' });
    assertJsonError(res, 400, MSG.order);
  });
});

describe('rule 1 content type', () => {
  const ctx = useServer();
  const rejected = [
    undefined, '', 'text/plain', 'application/jsonx', 'application/json-patch+json',
    'application/x-json', 'json', 'application/json, text/plain', 'application/ json', 'text/json',
  ];
  for (const contentType of rejected) {
    it(`rejects ${label(contentType)}`, async () => {
      const res = await postBooking(ctx.port, booking(), { contentType });
      assertJsonError(res, 415, MSG.type);
    });
  }
  const accepted = [
    'application/json', 'Application/JSON ; charset=x', 'APPLICATION/JSON',
    'application/json;charset=utf-8', 'application/json;', 'application/json\t;x',
    ' application/json', '\tapplication/json\t',
  ];
  for (const contentType of accepted) {
    it(`accepts ${label(contentType)}`, async () => {
      const value = booking();
      assertCreated(await postBooking(ctx.port, value, { contentType }), value);
    });
  }
});

describe('rule 2 body size', () => {
  const ctx = useServer();
  const post = (body) => postBooking(ctx.port, body, { raw: true });
  const sized = [[10000, 201], [10001, 413]];
  for (const [size, status] of sized) {
    it(`space padded body of ${size} bytes`, async () => {
      const value = booking();
      const body = paddedBody(value, size);
      assert.equal(body.length, size);
      const res = await post(body);
      if (status === 201) assertCreated(res, value);
      else assertJsonError(res, 413, MSG.size);
    });
    it(`multi-byte padded body of ${size} bytes`, async () => {
      const value = booking();
      const { buffer, text } = accentBody(value, size);
      assert.equal(Buffer.byteLength(text), size);
      assert.ok(text.length < 10000);
      const res = await post(buffer);
      if (status === 201) assertCreated(res, value);
      else assertJsonError(res, 413, MSG.size);
    });
    it(`chunked body of ${size} bytes`, async () => {
      const value = booking();
      const body = paddedBody(value, size);
      const chunks = chunked(body);
      assert.equal(chunks.reduce((n, c) => n + c.length, 0), size);
      const res = await post(chunks);
      if (status === 201) assertCreated(res, value);
      else assertJsonError(res, 413, MSG.size);
    });
  }
});

describe('rule 3 body must be a JSON object', () => {
  const ctx = useServer();
  const notObjects = ['', ' ', 'not json', 'null', '[]', '[{}]', '"str"', '1', 'true', 'false', '{', '{"room":"Aurora",}'];
  for (const text of notObjects) {
    it(`rejects ${JSON.stringify(text)}`, async () => {
      assertJsonError(await postBooking(ctx.port, text, { raw: true }), 400, MSG.object);
    });
  }

  it('rejects a body with a byte order mark', async () => {
    const bom = Buffer.from([0xef, 0xbb, 0xbf]);
    const body = Buffer.concat([bom, Buffer.from(JSON.stringify(booking()))]);
    assertJsonError(await postBooking(ctx.port, body, { raw: true }), 400, MSG.object);
  });

  it('turns invalid UTF-8 inside a string into U+FFFD', async () => {
    const value = booking();
    const head = JSON.stringify({ ...value, title: 'A_B' }).split('A_B');
    const body = Buffer.concat([Buffer.from(head[0] + 'A'), Buffer.from([0xff]), Buffer.from('B' + head[1])]);
    assertCreated(await postBooking(ctx.port, body, { raw: true }), { ...value, title: 'A�B' });
  });

  it('accepts surrounding whitespace and newlines', async () => {
    const value = booking();
    const body = ' \n\t\r\n' + JSON.stringify(value) + '\n \r\n';
    assertCreated(await postBooking(ctx.port, body, { raw: true }), value);
  });

  it('ignores extra keys and assigns its own id', async () => {
    const value = booking();
    const res = await postBooking(ctx.port, { ...value, id: 99, extra: 'x', nextId: 5 });
    const created = assertCreated(res, value);
    assert.notEqual(created.id, 99);
  });
});

describe('rule 4 room', () => {
  const ctx = useServer();
  const rejected = ['aurora', 'AURORA', ' Aurora', 'Aurora ', 'Dune', '', undefined, null, 1, ['Aurora'], {}];
  for (const room of rejected) {
    it(`rejects ${label(room)}`, async () => {
      assertJsonError(await postBooking(ctx.port, booking({ room })), 400, MSG.room);
    });
  }
  for (const room of ['Aurora', 'Borealis', 'Cosmos']) {
    it(`accepts ${room}`, async () => {
      const value = booking({ room });
      assertCreated(await postBooking(ctx.port, value), value);
    });
  }
});

describe('rule 5 title', () => {
  const ctx = useServer();
  const rejected = [
    undefined, null, 5, true, [], '', ' ', '   \t\n ', ' ', '　﻿',
    'a'.repeat(81), '😀'.repeat(40) + 'a',
  ];
  for (const title of rejected) {
    it(`rejects ${label(title).slice(0, 30)}`, async () => {
      assertJsonError(await postBooking(ctx.port, booking({ title })), 400, MSG.title);
    });
  }

  const accepted = [
    ['a'.repeat(80), 'a'.repeat(80)],
    ['  ' + 'a'.repeat(80) + '\t\n', 'a'.repeat(80)],
    [' x ', 'x'],
    [' x ', 'x'],
    [' x ', 'x'],
    ['😀'.repeat(40), '😀'.repeat(40)],
    ['​', '​'],
    ['<b>x</b>', '<b>x</b>'],
    ['a  b', 'a  b'],
  ];
  for (const [title, stored] of accepted) {
    it(`accepts ${label(title).slice(0, 30)}`, async () => {
      const value = booking({ title });
      const created = assertCreated(await postBooking(ctx.port, value), { ...value, title: stored });
      const list = await request(ctx.port, { path: `/api/bookings?date=${value.date}` });
      assert.deepEqual(list.json(), { bookings: [created] });
    });
  }
});

describe('failed POSTs do not consume ids', () => {
  const ctx = useServer();
  it('next valid booking gets last id + 1', async () => {
    const first = booking();
    const last = assertCreated(await postBooking(ctx.port, first), first);
    const failing = [
      () => postBooking(ctx.port, booking(), { contentType: 'text/plain' }),
      () => postBooking(ctx.port, Buffer.alloc(10001, ' '), { raw: true }),
      () => postBooking(ctx.port, '[1', { raw: true }),
      () => postBooking(ctx.port, booking({ room: 'x' })),
      () => postBooking(ctx.port, first),
    ];
    const statuses = [];
    for (const send of failing) statuses.push((await send()).status);
    assert.deepEqual(statuses, [415, 413, 400, 400, 409]);
    const next = booking();
    const created = assertCreated(await postBooking(ctx.port, next), next);
    assert.equal(created.id, last.id + 1);
  });
});
